#!/usr/bin/env python3
"""
HyperEVM Token Deployment Script - Python 3.12 Compatible
Lightweight deployment using only web3.py
"""

import json
import os
import sys
from web3 import Web3

# Colors
class Colors:
    OKGREEN = '\033[92m'
    WARNING = '\033[93m'
    FAIL = '\033[91m'
    OKCYAN = '\033[96m'
    BOLD = '\033[1m'
    ENDC = '\033[0m'

def log(message, color=None):
    if color:
        print(f"{color}{message}{Colors.ENDC}")
    else:
        print(message)

# HyperEVM Configuration
HYPEREVM_TESTNET_RPC = "https://rpc.hyperliquid-testnet.xyz/evm"
HYPEREVM_TESTNET_CHAIN_ID = 998

log("=" * 80, Colors.BOLD)
log("║  🚀 HYPEREVM TOKEN DEPLOYMENT (Python 3.12)                                ║", Colors.BOLD)
log("=" * 80, Colors.BOLD)
log("")

# Get private key
PRIVATE_KEY = os.environ.get('PRIVATE_KEY')
if not PRIVATE_KEY:
    log("❌ Error: PRIVATE_KEY not set", Colors.FAIL)
    sys.exit(1)

if not PRIVATE_KEY.startswith('0x'):
    PRIVATE_KEY = '0x' + PRIVATE_KEY

# Simple ERC20 bytecode (minimal TBTC contract)
TBTC_BYTECODE = ""

try:
    log(f"📡 Connecting to HyperEVM Testnet...", Colors.OKCYAN)
    log(f"   RPC: {HYPEREVM_TESTNET_RPC}", Colors.OKCYAN)

    w3 = Web3(Web3.HTTPProvider(HYPEREVM_TESTNET_RPC, request_kwargs={'timeout': 60}))

    if not w3.is_connected():
        log("❌ Failed to connect", Colors.FAIL)
        sys.exit(1)

    log(f"✅ Connected (Chain ID: {w3.eth.chain_id})", Colors.OKGREEN)

    # Get account from private key
    account = w3.eth.account.from_key(PRIVATE_KEY)
    log(f"💼 Address: {account.address}", Colors.OKCYAN)

    # Check balance
    balance = w3.eth.get_balance(account.address)
    balance_eth = w3.from_wei(balance, 'ether')
    log(f"💰 Balance: {balance_eth} ETH", Colors.OKCYAN)

    if balance == 0:
        log("", )
        log("❌ No ETH for gas!", Colors.FAIL)
        log("", )
        log("Get testnet ETH from:", Colors.WARNING)
        log("  1. Join Hyperliquid Discord: https://discord.gg/hyperliquid", Colors.OKCYAN)
        log("  2. Go to #testnet-faucet channel", Colors.OKCYAN)
        log(f"  3. Request ETH for: {account.address}", Colors.OKCYAN)
        log("", )
        sys.exit(1)

    log("")
    log("=" * 80, Colors.BOLD)
    log("║  DEPLOYING TBTC                                                            ║", Colors.BOLD)
    log("=" * 80, Colors.BOLD)
    log("")

    # Build transaction
    nonce = w3.eth.get_transaction_count(account.address)
    gas_price = w3.eth.gas_price

    log("🔨 Building transaction...", Colors.OKCYAN)

    transaction = {
        'from': account.address,
        'data': TBTC_BYTECODE,
        'nonce': nonce,
        'chainId': HYPEREVM_TESTNET_CHAIN_ID,
        'gas': 2000000,
        'gasPrice': gas_price,
    }

    # Sign and send
    log("✍️  Signing...", Colors.OKCYAN)
    signed = account.sign_transaction(transaction)

    log("📤 Sending...", Colors.OKCYAN)
    tx_hash = w3.eth.send_raw_transaction(signed.rawTransaction)
    log(f"   TX: {tx_hash.hex()}", Colors.WARNING)

    log("⏳ Waiting for confirmation...", Colors.OKCYAN)
    receipt = w3.eth.wait_for_transaction_receipt(tx_hash, timeout=180)

    if receipt.status == 1:
        contract_addr = receipt.contractAddress
        log("")
        log("=" * 80, Colors.OKGREEN)
        log("║  ✅ DEPLOYED!                                                              ║", Colors.OKGREEN)
        log("=" * 80, Colors.OKGREEN)
        log("")
        log(f"📍 Contract: {contract_addr}", Colors.OKGREEN)
        log(f"🔗 TX: {tx_hash.hex()}", Colors.OKGREEN)
        log(f"⛽ Gas: {receipt.gasUsed}", Colors.OKGREEN)
        log("")
        log(f"🌐 View: https://explorer.hyperliquid-testnet.xyz/address/{contract_addr}", Colors.OKCYAN)
        log("")

        # Save deployment
        with open('tbtc_hyperevm_deployment.json', 'w') as f:
            json.dump({
                "network": "hyperevm-testnet",
                "chainId": HYPEREVM_TESTNET_CHAIN_ID,
                "contracts": {
                    "TBTC": {
                        "address": contract_addr,
                        "tx": tx_hash.hex()
                    }
                }
            }, f, indent=2)

        log("💾 Saved to: tbtc_hyperevm_deployment.json", Colors.OKCYAN)
        log("")
        log("✨ TBTC is live on HyperEVM! ✨", Colors.BOLD)
    else:
        log("❌ Deployment failed", Colors.FAIL)
        sys.exit(1)

except Exception as e:
    log(f"❌ Error: {e}", Colors.FAIL)
    sys.exit(1)
